const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '地图比例尺 1:10000' },
      { kind: 'text', payload: '图上两地距离 7 厘米' },
      { kind: 'text', payload: '实际距离 70000 厘米' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '7 厘米' }
    ];
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 640;
    var H = (input.viewport && input.viewport.heightDu) || 360;
    var left = W * 0.12;
    var right = W * 0.88;
    var y = H * 0.50;
    var n = 7;
    var gap = (right - left) / n;
    var tickH = Math.max(8, Math.min(18, H * 0.045));
    var majorH = tickH * 1.6;
    var labelGap = Math.max(26, H * 0.08);
    var cmds = [];
    cmds = cmds.concat(visualSdk.polyline([[left, y], [right, y]]));
    for (var i = 0; i <= n; i++) {
      var x = left + gap * i;
      var h = (i === 0 || i === n) ? majorH : tickH;
      cmds = cmds.concat(visualSdk.polyline([[x, y - h], [x, y + h]]));
    }
    var titleY = H * 0.16;
    var mapLabelY = y - majorH - labelGap * 0.9;
    var endLabelY = y + majorH + labelGap * 0.5;
    var actualLabelY = y + majorH + labelGap * 1.8;
    var centerX = (left + right) / 2;
    return {
      schemaVersion: 1,
      sceneId: 'scale-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'scale', commands: cmds }],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'scale', fill: '#26354a', stroke: { width: 2 } },
          { type: 'label', contentId: 'c0', anchor: { x: centerX, y: titleY }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: 'c1', anchor: { x: centerX, y: mapLabelY }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: 'c2', anchor: { x: centerX, y: actualLabelY }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: 'c3', anchor: { x: left, y: endLabelY }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: 'c4', anchor: { x: right, y: endLabelY }, hAlign: 'center', vAlign: 'top', color: '#26354a' }
        ]
      }
    };
  }
};
